export async function request(path,options={}){const response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await response.json()}catch{throw new Error('The server could not be reached. Please try again.')}if(!response.ok){const error=new Error(data.error||'Request failed.');error.status=response.status;throw error}return data;}
export const authProvider={async currentUser(){return (await request('me')).user},async login(email,password){return (await request('login',{method:'POST',body:JSON.stringify({email,password})})).user},async register(email,password){return (await request('register',{method:'POST',body:JSON.stringify({email,password})})).user},async logout(){await request('logout',{method:'POST',body:'{}'})}};
export const layoutRepository={async load(){return (await request('layout')).document},async save(document){await request('layout',{method:'PUT',body:JSON.stringify(document)})}};
export function createSaveQueue(repository,onStatus,delay=600){let pending=null,timer=null,running=null,error=null;async function run(){if(running)return running;if(!pending)return;running=(async()=>{while(pending){const doc=pending;pending=null;onStatus('saving');try{await repository.save(doc);error=null}catch(e){if(!pending)pending=doc;error=e;onStatus('error',e);throw e}}onStatus('saved')})().finally(()=>{running=null});return running}return {schedule(doc){pending=structuredClone(doc);clearTimeout(timer);onStatus('pending');timer=setTimeout(()=>{run().catch(()=>{})},delay)},async flush(){clearTimeout(timer);if(running)await running;if(pending)await run();if(error)throw error},get dirty(){return !!pending||!!running}};}
